#include <errno.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct { uint8_t *p; size_t n; uint32_t base; } Image;
static uint16_t le16(const uint8_t*p){return (uint16_t)(p[0]|p[1]<<8);}
static uint32_t le32(const uint8_t*p){return (uint32_t)p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24;}
static void die(const char*s){fprintf(stderr,"phase4_d14_static: %s\n",s);exit(2);}
static uint8_t*load(const char*path,size_t*n){FILE*f=fopen(path,"rb");long z;uint8_t*p;if(!f){fprintf(stderr,"%s: %s\n",path,strerror(errno));exit(2);}if(fseek(f,0,SEEK_END)||(z=ftell(f))<0||fseek(f,0,SEEK_SET))die("seek failed");p=malloc((size_t)z);if(!p)die("out of memory");if(fread(p,1,(size_t)z,f)!=(size_t)z)die("short read");fclose(f);*n=(size_t)z;return p;}
static Image exe_image(const char*path){size_t n;uint8_t*f=load(path,&n);Image x;if(n<0x800||memcmp(f,"PS-X EXE",8))die("input is not PS-X EXE");x.base=le32(f+0x18);x.n=le32(f+0x1c);if(x.n>n-0x800)die("PS-X EXE text size exceeds file");x.p=malloc(x.n);if(!x.p)die("out of memory");memcpy(x.p,f+0x800,x.n);free(f);return x;}
static uint32_t word(const Image*x,uint32_t va){size_t o;if(va<x->base||(o=(size_t)(va-x->base))+4>x->n)die("virtual address outside image");return le32(x->p+o);}
static const char*vmname(unsigned o){static const char*n[26]={"jump_back","park_end","wait","wait_random","random_dir_step","path_next_waypoint","park_seek","park_arrive_test","park_arrive_stop","branch_if_s3","park_path","seek_path_endpoint","call_native","flags_mask","anim_clip_load","cond_noise_mask","chase_radius_scratch","player_proximity","park_seek18","park19","branch20","park21","done_disable","set_byte_params","op24","op25"};return o<26?n[o]:"invalid";}
static unsigned vmlen(unsigned o){static const uint8_t n[26]={4,2,4,6,2,2,2,2,2,4,2,4,4,6,6,4,4,4,2,2,4,2,2,6,4,2};return o<26?n[o]:0;}
static void vm(const Image*x,uint32_t pc,uint32_t end,const char*name){printf("VM %s 0x%08x..0x%08x\n",name,pc,end);while(pc<end){size_t o=(size_t)(pc-x->base);int raw,idx;unsigned len;if(pc<x->base||o+2>x->n)die("VM address outside image");raw=(int16_t)le16(x->p+o);idx=raw+1;if(idx<0||idx>25)die("invalid VM opcode index");len=vmlen((unsigned)idx);if(!len||pc+len>end||o+len>x->n)die("invalid VM opcode/length");printf("  0x%08x raw=%d idx=%d %-20s",pc,raw,idx,vmname((unsigned)idx));for(unsigned i=2;i<len;i+=2)printf(" %u",le16(x->p+o+i));if(idx==0)printf(" target=0x%08x",pc-2u*le16(x->p+o+2));if(idx==12&&le16(x->p+o+2)==2)printf(" native=0x80057920");putchar('\n');pc+=len;}}
static const char*mname(uint32_t w){unsigned op=w>>26,fn=w&63;if(op==0){switch(fn){case 0:return"sll";case 3:return"sra";case 8:return"jr";case 0x12:return"mflo";case 0x18:return"mult";case 0x21:return"addu";case 0x23:return"subu";case 0x2a:return"slt";default:return"special";}}switch(op){case 2:return"j";case 3:return"jal";case 4:return"beq";case 5:return"bne";case 6:return"blez";case 7:return"bgtz";case 9:return"addiu";case 0xc:return"andi";case 0xd:return"ori";case 0xf:return"lui";case 0x20:return"lb";case 0x21:return"lh";case 0x23:return"lw";case 0x24:return"lbu";case 0x25:return"lhu";case 0x28:return"sb";case 0x29:return"sh";case 0x2b:return"sw";default:return"other";}}
static void mips_window(const Image*x,uint32_t pc,uint32_t end,const char*name){printf("MIPS %s 0x%08x..0x%08x\n",name,pc,end);for(;pc<end;pc+=4){uint32_t w=word(x,pc);printf("  0x%08x %08x %-7s rs=%u rt=%u rd=%u imm=%d/0x%04x\n",pc,w,mname(w),(w>>21)&31,(w>>16)&31,(w>>11)&31,(int16_t)w,w&0xffff);}}
static void homing_candidates(const Image*x){unsigned hits=0;puts("HOMING_FLAG_CANDIDATES");for(size_t o=0;o+52<x->n;o+=4){uint32_t a=le32(x->p+o);unsigned op=a>>26,rt=a>>16&31;if(!((op==0x23||op==0x25||op==0x21||op==0x24||op==0x20)&&(a&0xffff)==0x005c))continue;for(unsigned k=1;k<=12;k++){uint32_t w=le32(x->p+o+4*k);if((w>>26)==0x0c&&((w>>21)&31)==rt&&(w&0xffff)==1){printf("  load=0x%08x andi_bit1=0x%08x\n",x->base+(uint32_t)o,x->base+(uint32_t)o+4*k);++hits;break;}}}printf("candidate_count=%u\n",hits);}
int main(int argc,char**argv){Image exe;static const struct{uint32_t pc,w;}gate[]={{0x8005747c,0x9483005c},{0x80057484,0x30620001},{0x80057488,0x10400016},{0x8005748c,0x306200a0},{0x80057490,0x14400014}};if(argc!=2){fprintf(stderr,"usage: %s SCUS_942.88\n",argv[0]);return 2;}exe=exe_image(argv[1]);printf("EXE base=0x%08x size=%zu\n",exe.base,exe.n);for(size_t i=0;i<sizeof gate/sizeof gate[0];i++)if(word(&exe,gate[i].pc)!=gate[i].w)die("homing gate word mismatch");puts("homing_gate_words=5/5");vm(&exe,0x8007755c,0x80077578,"dragonfly");vm(&exe,0x80077578,0x800775c8,"bee");mips_window(&exe,0x8005747c,0x8005749c,"homing_target_filter");mips_window(&exe,0x8004c9f0,0x8004ca24,"opcode18_contact_transition");mips_window(&exe,0x80057920,0x80057960,"bee_native_sub2_entry");mips_window(&exe,0x8004a20c,0x8004a234,"dragonfly_callback");homing_candidates(&exe);free(exe.p);return 0;}
